const std=@import("std");
fn puti(o:[*]u8,x:i64)void{const b=@as(u64,@bitCast(x));for(0..8)|k|o[k]=@truncate(b>>(8*k));}
export fn naive_bayes(v:[*]const i64,n:usize,o:[*]u8,cap:usize)i64{if(n<6)return -1;const nr=v[0];const f=v[1];if(nr<2 or nr>8 or f<1 or f>3 or n!=@as(usize,@intCast(2+nr*(f+1)+f)))return -1;var labs=[_]usize{0}**8;var order=[_]i64{0}**3;var counts=[_]usize{0}**3;var cc:usize=0;var x=[_] [3]f64{[_]f64{0}**3}**8;var p:usize=2;for(0..@intCast(nr))|r|{const lab=v[p];p+=1;if(lab<0 or lab>2)return -1;var c:usize=0;while(c<cc and order[c]!=lab)c+=1;if(c==cc){order[cc]=lab;cc+=1;}labs[r]=c;counts[c]+=1;for(0..@intCast(f))|j|{const z=v[p];p+=1;if(z < -10000 or z>10000)return -1;x[r][j]=@as(f64,@floatFromInt(z))/1000.0;}}if(cc<2)return -1;var best=-std.math.inf(f64);var ans=order[0];for(0..cc)|c|{var score=@log(@as(f64,@floatFromInt(counts[c]))/@as(f64,@floatFromInt(nr)));for(0..@intCast(f))|j|{var mean:f64=0;for(0..@intCast(nr))|r|{if(labs[r]==c)mean+=x[r][j];}mean/=@as(f64,@floatFromInt(counts[c]));var variance:f64=0;for(0..@intCast(nr))|r|{if(labs[r]==c){const d=x[r][j]-mean;variance+=d*d;}}variance=@max(variance/@as(f64,@floatFromInt(counts[c])),1e-9);const raw=v[p+j];if(raw < -10000 or raw>10000)return -1;const q=@as(f64,@floatFromInt(raw))/1000.0;score+=-0.5*@log(6.283185307179586*variance)-(q-mean)*(q-mean)/(2*variance);}if(score>best){best=score;ans=order[c];}}if(cap<8)return -2;puti(o,ans);return 8;}
